-- Schema baseline at 0112_restore_migration_only_objects (Launch Phase 3, #770). GENERATED by
-- lib/db/scripts/generate-baseline.ts — do not edit by hand; regenerate.
-- Applied by lib/db/src/migrate.ts to an EMPTY database only, in one
-- transaction with the ledger rows for every migration up to the cutoff.
-- Seed rows' timestamps are the generation run's, so two runs differ there
-- and nowhere else.

CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;


