INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('ai_max_images_per_gender', '34', 'integer', 'AI Max Images Per Fact Per Gender', 'Maximum AI images stored per gender per fact (3 genders × this value ≈ total per-fact cap). Oldest images are evicted when reached.', 1, 500, false, '2026-10-27 18:30:18.369148+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('user_max_images', '1000', 'integer', 'User Max Image Storage', 'Total image storage limit per paid user, combining AI-generated images and uploaded photos. Oldest AI images are evicted when limit is reached.', 10, 10000, false, '2026-10-27 18:30:18.369148+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('budget_limit_registered_usd', '0.50', 'float', 'Registered Tier Generation Budget (USD)', 'Maximum fal.ai generation spend per budget period for users on the Registered Tier (USD).', 0, 10000, false, '2026-10-27 18:30:18.522301+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('budget_limit_legendary_usd', '10.00', 'float', 'Legendary Tier Generation Budget (USD)', 'Maximum fal.ai generation spend per budget period for users on the Legendary Tier (USD). Applies globally unless a per-user override is set.', 0, 10000, false, '2026-10-27 18:30:18.522301+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('arachnid_shield_enabled', 'true', 'boolean', 'Arachnid Shield Enabled', 'When true, every face-source upload is scanned via Project Arachnid Shield before storage.', NULL, NULL, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('arachnid_fail_open', 'false', 'boolean', 'Arachnid Fail-Open', 'If false, upload is rejected when the Arachnid scan errors. Recommended: false.', NULL, NULL, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('nsfw_classifier_endpoint', 'fal-ai/imageutils/nsfw', 'text', 'NSFW Classifier Endpoint', 'fal.ai endpoint id used as the synchronous NSFW gate on every generated/uploaded image.', NULL, NULL, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('nsfw_classifier_threshold', '0.85', 'text', 'NSFW Classifier Threshold', 'Probability score at or above which an image is treated as NSFW. Stored as text so we can use floats.', NULL, NULL, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('nsfw_classifier_timeout_ms', '15000', 'integer', 'NSFW Classifier Timeout (ms)', 'Max time to wait for the NSFW classifier before failing closed.', 1000, 120000, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('fal_safety_tolerance_pulid', '1', 'text', 'fal.ai Safety Tolerance (PuLID/IP-Adapter)', 'Strictest = "1". Applied to PuLID and IP-Adapter image generation when the model accepts it.', NULL, NULL, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('upload_rate_limit_registered_per_day', '20', 'integer', 'Upload Cap — Registered (per day)', 'Daily face-source upload cap for free/registered users.', 1, 1000, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('upload_rate_limit_legendary_per_day', '200', 'integer', 'Upload Cap — Legendary (per day)', 'Daily face-source upload cap for Legendary tier users.', 1, 10000, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('name_validation_max_words', '3', 'integer', 'Name Validation: Max Words', 'Hard cap on the number of whitespace-separated words in displayName/firstName/lastName.', 1, 10, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('name_validation_max_chars_per_word', '20', 'integer', 'Name Validation: Max Chars Per Word', 'Hard cap on each word inside displayName/firstName/lastName.', 1, 80, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('name_denylist_patterns', '[]', 'text', 'Name Denylist Patterns (JSON)', 'JSON array of regex patterns rejected on name fields. Keep short — false positives are user-facing.', NULL, NULL, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('quarantine_evidence_retention_days', '90', 'integer', 'Quarantine Evidence Retention (days)', 'Minimum days quarantined evidence must be preserved before deletion is permitted.', 30, 365, false, '2026-10-27 18:30:18.594528+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('share_copy_twitter_template', '{fact_text}', 'text', 'Share copy — Twitter/X body', 'Tweet body for the Twitter/X share button. The permalink is appended automatically by the share-intent URL; do not include it in this template. Variables: {name}, {fact_text}, {permalink}.', NULL, NULL, false, '2026-10-27 18:30:18.666872+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('share_copy_twitter_hashtags', 'overhype,legendsaremadeup', 'text', 'Share copy — Twitter/X hashtags', 'Comma-separated hashtags (no # prefix). Passed to the Twitter/X intent URL as &hashtags=…', NULL, NULL, false, '2026-10-27 18:30:18.666872+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('share_copy_email_subject_template', 'A meme of {name} on overhype.me', 'text', 'Share copy — Email subject', 'mailto: subject line for desktop browsers without Web Share API. Variables: {name}, {fact_text}, {permalink}.', NULL, NULL, false, '2026-10-27 18:30:18.666872+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('share_copy_email_body_template', '{name} thought you''d appreciate this:

"{fact_text}"

See it: {permalink}

— Sent from overhype.me, where legends are made up.', 'text', 'Share copy — Email body', 'mailto: body for desktop browsers without Web Share API. Plain text (mailto: does not support HTML). Variables: {name}, {fact_text}, {permalink}.', NULL, NULL, false, '2026-10-27 18:30:18.666872+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('share_copy_web_share_title_template', '{name} on overhype.me', 'text', 'Share copy — Web Share title', 'Title passed to navigator.share() — shown as the headline in the OS share sheet. Variables: {name}, {fact_text}, {permalink}.', NULL, NULL, false, '2026-10-27 18:30:18.666872+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('share_copy_web_share_text_template', '{fact_text}', 'text', 'Share copy — Web Share text', 'Body passed to navigator.share() — shown beneath the title in the OS share sheet. Variables: {name}, {fact_text}, {permalink}.', NULL, NULL, false, '2026-10-27 18:30:18.666872+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('engine_revision', '1', 'integer', 'Engine Revision', 'Manual marker bumped on a major engine/LLM change. Facts whose enrichment was processed under an older revision read as stale for reprocess in Taxonomy Health.', NULL, NULL, false, '2026-10-27 18:30:18.806395+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('instance_heartbeat_ttl_minutes', '15', 'integer', 'Worker instance heartbeat TTL (minutes)', 'How long a worker instance may go without writing a lane heartbeat before it is treated as departed and pruned. Too low and a briefly-paused instance is forgotten; too high and an autoscale scale-down looks like a stalled lane.', 1, 1440, false, '2026-10-27 18:30:18.904469+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('grace_sweep_interval_seconds', '3600', 'integer', 'Membership grace sweep interval (s)', 'How often the convergence sweep recomputes users whose grace window has expired. Lateness here is cosmetic — the read path already enforces the deadline — so this is cheaper than reconciliation and runs more often.', 1, 86400, false, '2026-10-27 18:30:18.906745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('grace_sweep_alert_after_seconds', '21600', 'integer', 'Membership grace sweep alert after (s)', 'How long the grace sweep may keep failing before an alert fires. The sweep dying does not revoke anyone late; what degrades is the accuracy of the stored tier, which this surfaces.', 1, 604800, false, '2026-10-27 18:30:18.906745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('lease_ttl_seconds', '90', 'integer', 'Entitlement source lease TTL (s)', 'How long one retrieval-and-apply may hold a per-source lease. Must exceed the whole bounded budget: the Stripe retrieval PHASE (every request a prepare makes under one lease — the subscription, its paginated items, a product per item, and for a past_due refresh the invoice/payment/charge lists behind the grace anchor) plus the apply transaction (lock timeout x attempts + backoff), times a 1.5 margin for scheduling jitter. Too short and a valid holder expires mid-work and its fenced write aborts; too long and a crashed holder wedges that source until expiry.', 83, 600, false, '2026-10-27 18:30:18.906745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('lease_waiter_timeout_seconds', '5', 'integer', 'Entitlement lease waiter timeout (s)', 'How long a writer waits for a busy source lease before giving up. A waiter that times out abandons its write rather than proceeding unordered; Stripe redelivers the event, so the write is retried rather than lost. This trades latency for nothing and may be short.', 1, 60, false, '2026-10-27 18:30:18.906745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('ncmec_submission_enabled', 'false', 'boolean', 'NCMEC Submission Enabled', 'Master switch for automated CyberTipline filing. False means the submission job no-ops and reports stay pending — today''s behavior. Writable only through the guarded /admin/safety config endpoint, which refuses activation while the backlog audit is incomplete.', NULL, NULL, false, '2026-10-27 18:30:18.916745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('ncmec_ispws_environment', 'test', 'text', 'NCMEC ISPWS Environment', 'Which CyberTipline host receives submissions: "test" (exttest.cybertip.org, nothing is filed for real) or "production" (report.cybertip.org). Writable only through the guarded /admin/safety config endpoint.', NULL, NULL, false, '2026-10-27 18:30:18.916745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('ncmec_report_classifier_hits', 'false', 'boolean', 'NCMEC Report Classifier Hits', 'Whether classifier-sourced quarantines are filed to NCMEC. Hard-blocked in code until NCMEC answers which incident type applies to a classifier hit — this key alone does not enable it.', NULL, NULL, false, '2026-10-27 18:30:18.916745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('ncmec_backlog_audit_cutoff', '', 'text', 'NCMEC Backlog Audit Cutoff', 'ISO timestamp bounding the pre-activation backlog audit''s SCOPE, captured before review begins. Reports created at or after it are new-code rows and need no audit. Write-once: moving it would shift the scope of an in-progress audit under the operator.', NULL, NULL, false, '2026-10-27 18:30:18.916745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('ncmec_backlog_audit_completed_at', '', 'text', 'NCMEC Backlog Audit Completed At', 'ISO timestamp marking the operator''s declaration that the backlog audit is finished. Deliberately separate from the cutoff: the cutoff bounds the work, this records that it was done.', NULL, NULL, false, '2026-10-27 18:30:18.916745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('ncmec_safety_alert_email', '', 'text', 'NCMEC Safety Alert Email', 'Fallback recipient for submission-failure alerts when no admin has notifications enabled. Not a reserved key — but production activation is refused unless a recipient resolves, and this key cannot be emptied while production is live.', NULL, NULL, false, '2026-10-27 18:30:18.916745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('async_job_ncmec_submit_max_attempts', '8', 'integer', 'NCMEC Submit — Max Attempts', 'Retry budget for the ncmec_submit queue. With the seeded fourth delay this gives a ~98.6 hour horizon, which is what lets a multi-day CyberTipline outage resolve itself instead of producing a terminal backlog. Lowering it silently shortens that horizon.', 1, 20, false, '2026-10-27 18:30:18.916745+00', NULL, NULL);
INSERT INTO public.admin_config (key, value, data_type, label, description, min_value, max_value, is_public, updated_at, updated_by_id, value_label) VALUES ('async_job_ncmec_submit_retry_delay_4_ms', '86400000', 'integer', 'NCMEC Submit — 4th Retry Delay (ms)', 'Delay before the fourth and subsequent retries of an ncmec_submit job (24h). The queue default of 8h would cut the retry horizon to ~10.5 hours while every surface still reported success.', 60000, 604800000, false, '2026-10-27 18:30:18.916745+00', NULL, NULL);

