INSERT INTO public.look_styles (id, label, description, prompt_suffix, prompt_suffix_reference, preview_image_path, sort_order, is_active, created_at, updated_at) VALUES ('cinematic', 'Cinematic', 'Dramatic widescreen movie still with deep shadows and warm highlights.', 'Rendered in cinematic film style: the look of a widescreen movie still with filmic color grading, volumetric lighting, and subtle lens flare.', 'Reimagine this scene in cinematic film style: the look of a widescreen movie still with filmic color grading, volumetric lighting, and subtle lens flare.', NULL, 2, true, '2026-10-27 18:30:18.705271+00', '2026-10-27 18:30:18.705271+00');
